use std :: fmt ; use super :: * ; impl CommandType { # [doc = " Returns the string representation of the command type."] # [doc = ""] # [doc = " This is the canonical way to convert a CommandType to a string"] # [doc = " for display purposes."] pub const fn as_str (& self) -> & 'static str { match self { Self :: Command => "command" , Self :: Agent => "agent" , Self :: Custom => "custom" , } } }